'use strict';
const STORE='makmal-uasa-sains6-v1',DURATION=75*60*1000;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=QUESTIONS.flatMap(q=>q.fields.map(f=>({...f,section:q.section,qid:q.id})));
let state=null,storageOK=true;
try{const raw=localStorage.getItem(STORE);if(raw){const s=JSON.parse(raw);if(s.version===1&&Number.isFinite(s.started)&&s.answers&&typeof s.answers==='object'&&['exam','result'].includes(s.status))state=s;}}catch{storageOK=false;}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{storageOK=false;}}
function norm(s){return String(s??'').toLowerCase().normalize('NFKC').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();}
function contains(s,t){return new RegExp('(?:^|\\s)'+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:$|\\s)').test(s);}
function answered(f){let a=state.answers[f.id];return f.type==='table'?Array.isArray(a)&&a.length===6&&a.every(v=>String(v).trim()):f.type==='choice'?Number.isInteger(a):typeof a==='string'&&a.trim().length>0;}
function anyAnswer(f){let a=state.answers[f.id];return f.type==='table'?Array.isArray(a)&&a.some(v=>String(v).trim()):answered(f);}
function autoScore(f){const a=state.answers[f.id];if(f.type==='choice')return a===f.answer?1:0;
 if(f.type==='table'){if(!Array.isArray(a))return 0;const n=a.map(norm);const headers=n[0]?.includes('ketinggian')&&contains(n[0],'m')&&n[1]?.includes('tekanan')&&contains(n[1],'kpa');const pairs=[[n[2]?.replace(/ /g,''),n[3]],[n[4]?.replace(/ /g,''),n[5]]];const data=pairs.some(v=>v[0]==='0'&&v[1]==='100')&&pairs.some(v=>v[0]==='2000'&&v[1]==='80');return Number(!!headers)+Number(data);}
 const n=norm(a);if(!n)return 0;
 // Written scores are suggestions only: parent review remains required.
 if(f.id==='c3c'){const concepts=[['larang','kuatkuasa'],['penetasan'],['perlindungan','wartakan'],['cahaya','lampu'],['kempen']];return Math.min(2,concepts.filter(v=>v.some(t=>n.includes(t))).length);}
 if(f.id==='c4a')return /^(jambatan\s+)?q$/.test(n)?1:0;
 if(f.id==='c4f'){return Number(/(?:^|\s)(?:menara\s+)?s(?:\s|$)/.test(n)&&!n.includes('menara r'))+Number(n.includes('tapak')&&/lebar|luas/.test(n));}
 return f.rules.reduce((sum,groups)=>sum+Number(groups.every(or=>or.some(t=>t.length===1?contains(n,t):n.includes(t)))),0);
}
function score(f){const m=state.overrides?.[f.id];return Number.isInteger(m)&&m>=0&&m<=f.max?m:autoScore(f);}
function total(section){return fields.filter(f=>!section||f.section===section).reduce((n,f)=>n+score(f),0);}
function grade(p){return p>=80?'A':p>=65?'B':p>=50?'C':p>=40?'D':'E';}
function tableHTML(rows){return '<div class="table-wrap"><table>'+rows.map((row,i)=>'<tr>'+row.map(cell=>`<${i?'td':'th'}>${esc(cell)}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';}
function toast(message){$('#toast')?.remove();const t=document.createElement('div');t.id='toast';t.role='status';t.textContent=message;document.body.appendChild(t);setTimeout(()=>t.remove(),3500);}
async function confirmAction(title,body,label='Teruskan'){const d=$('#confirm');$('#dialog-title').textContent=title;$('#dialog-body').textContent=body;$('#dialog-ok').textContent=label;d.returnValue='';d.showModal();return new Promise(r=>d.addEventListener('close',()=>r(d.returnValue==='confirm'),{once:true}));}
function welcome(){const resume=state?.status==='exam';$('#main').innerHTML=`<div class="hero"><section><div class="eyebrow">SEDIA UNTUK CABARAN SAINS?</div><h1>Fikir. Jawab.<br><span class="accent">Fahami sains.</span></h1><p class="muted">Latihan UASA Tahun 6 berdasarkan topik ulang kaji kamu. Cuba satu kertas penuh, kemudian kenal pasti bahagian yang boleh diperbaiki.</p><div class="meta-grid"><div><strong>50</strong><span>markah penuh</span></div><div><strong>75</strong><span>minit menjawab</span></div><div><strong>3</strong><span>bahagian</span></div></div><p class="start-warning">Jawab semua soalan. Jawapan disimpan pada pelayar ini secara automatik.</p></section><section class="card start-card"><span class="pill">KERTAS LATIHAN 01</span><h2>Jom uji kefahaman.</h2><label for="student">Nama panggilan <small>(pilihan)</small></label><input id="student" type="text" maxlength="60" placeholder="Contoh: Addeena" autocomplete="off" value="${esc(state?.name||'')}"><button class="full" id="start">${resume?'Sambung peperiksaan':state?.status==='result'?'Lihat keputusan':'Mula peperiksaan'} →</button>${state?'<button id="fresh" class="ghost full">Mulakan percubaan baharu</button>':''}<div class="notice"><strong>Bagaimana markah dikira?</strong><br>A & B ditanda secara automatik. Jawapan bertulis C menerima cadangan markah berdasarkan kata kunci dan perlu disemak ibu bapa mengikut skema sebelum gred disahkan.</div><p class="privacy">Tiada akaun diperlukan. Nama dan jawapan tidak dihantar ke pangkalan data. Rekod pada peranti ini sahaja.${storageOK?'':' Penyimpanan pelayar tidak tersedia; jangan tutup atau muat semula halaman.'}</p></section></div><div class="section-cards"><div class="card"><span class="pill">BAHAGIAN A</span><h3>10 soalan objektif</h3><p>10 markah · Pilih satu jawapan</p></div><div class="card"><span class="pill">BAHAGIAN B</span><h3>2 soalan berstruktur</h3><p>8 markah · Pilihan & padanan</p></div><div class="card"><span class="pill">BAHAGIAN C</span><h3>4 soalan KPS & aplikasi</h3><p>32 markah · Jawapan bertulis & jadual</p></div></div>`;
 $('#start').onclick=()=>{if(state){state.name=$('#student').value.trim();persist();if(state.status==='result')renderResults();else{if(Date.now()-state.started>=DURATION)submit(true);else renderExam();}}else start();};$('#fresh')?.addEventListener('click',async()=>{if(await confirmAction('Mulakan semula?','Rekod percubaan pada peranti ini akan digantikan. Muat turun keputusan dahulu jika perlu.','Mulakan baharu'))start();});}
function start(){const name=$('#student')?.value.trim()||state?.name||'';state={version:1,status:'exam',name,started:Date.now(),answers:{},flags:[],index:0,overrides:{},confirmed:false};persist();renderExam();}
function nav(){return ['A','B','C'].map(section=>`<div class="nav-group"><span class="eyebrow">BAHAGIAN ${section}</span><div class="nav-grid ${section==='A'?'':'compact'}">${QUESTIONS.map((q,i)=>q.section===section?`<button class="nav-btn ${i===state.index?'active':''} ${q.fields.every(answered)?'answered':''} ${state.flags.includes(q.id)?'flagged':''}" data-nav="${i}" aria-label="Bahagian ${section}, soalan ${q.title}, ${q.fields.every(answered)?'lengkap':'belum lengkap'}" ${i===state.index?'aria-current="step"':''}>${section}${q.id.slice(1)}</button>`:'').join('')}</div></div>`).join('');}
function fieldHTML(f){const a=state.answers[f.id];let input='';if(f.type==='choice'){input='<div class="options">'+f.options.map((o,i)=>`<label class="option"><input type="radio" name="${f.id}" value="${i}" ${a===i?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></label>`).join('')+'</div>';}else if(f.type==='table'){input='<div class="table-wrap"><table class="answer-table"><tbody>'+[0,1,2].map(r=>'<tr>'+[0,1].map(c=>{let j=r*2+c;return `<td><input type="text" data-table="${f.id}" data-cell="${j}" aria-label="${r===0?'Tajuk lajur '+(c+1):'Baris '+r+', lajur '+(c+1)}" placeholder="${r===0?'Tajuk & unit':'Nilai'}" maxlength="100" value="${esc(a?.[j]||'')}"></td>`;}).join('')+'</tr>').join('')+'</tbody></table></div>';}else input=`<textarea id="${f.id}" name="${f.id}" maxlength="2500" placeholder="Tulis jawapan kamu di sini...">${esc(a||'')}</textarea>`;
 return `<section class="field" aria-labelledby="label-${f.id}"><div class="field-label" id="label-${f.id}"><${f.type==='text'?'label for="'+f.id+'"':'span'}>${esc(f.label)}</${f.type==='text'?'label':'span'}><span class="marks">${f.max} markah</span></div>${input}</section>`;}
function updateProgress(){const done=fields.filter(answered).length;$('#progress-label').textContent=`${done}/${fields.length} jawapan`;$('#progress-fill').style.width=`${done/fields.length*100}%`;$('#nav-groups').innerHTML=nav();bindNav();$('#saved').textContent=storageOK?'Disimpan pada peranti ini.':'Penyimpanan tidak tersedia. Kekalkan halaman ini terbuka.';}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.index=+b.dataset.nav;persist();renderExam();});}
function renderExam(){if(Date.now()-state.started>=DURATION){submit(true);return;}state.index=Math.max(0,Math.min(15,state.index||0));const q=QUESTIONS[state.index];$('#main').innerHTML=`<div class="exam-top"><span id="progress-label"></span><div class="progress"><span id="progress-fill"></span></div><span class="timer" id="timer" aria-label="Baki masa"></span><button id="submit-top">Hantar</button></div><div class="exam-layout"><aside class="card sidebar"><h3>Peta soalan</h3><div class="nav-groups" id="nav-groups"></div><p class="legend">Hijau muda: lengkap<br>Garis kuning: semak kemudian</p></aside><article class="card question"><div class="q-heading"><span class="pill">BAHAGIAN ${q.section} · ${q.fields.reduce((n,f)=>n+f.max,0)} MARKAH</span><button class="ghost" id="flag" aria-pressed="${state.flags.includes(q.id)}">${state.flags.includes(q.id)?'★ Ditandakan':'☆ Semak nanti'}</button></div><h2 tabindex="-1" id="question-title">${esc(q.title)}</h2><p>${esc(q.intro)}</p>${q.table?tableHTML(q.table):''}${q.section==='C'?'<p class="muted" style="font-size:12px">Jawab dengan ayat sendiri. Markah bertulis akan disemak bersama skema selepas tamat.</p>':''}${q.fields.map(fieldHTML).join('')}<div class="actions"><button class="secondary left" id="prev" ${state.index===0?'disabled':''}>← Sebelum</button><button id="next">${state.index===15?'Hantar jawapan':'Seterusnya →'}</button></div><p class="save-note" id="saved" role="status"></p></article></div>`;
 updateProgress();tick();$('#submit-top').onclick=()=>submit(false);$('#prev').onclick=()=>navigate(-1);$('#next').onclick=()=>state.index===15?submit(false):navigate(1);
 $('#flag').onclick=()=>{state.flags=state.flags.includes(q.id)?state.flags.filter(v=>v!==q.id):[...state.flags,q.id];persist();renderExam();};
 document.querySelectorAll('input[type=radio]').forEach(el=>el.addEventListener('change',()=>{state.answers[el.name]=+el.value;persist();updateProgress();}));document.querySelectorAll('textarea').forEach(el=>el.addEventListener('input',()=>{state.answers[el.name]=el.value;persist();updateProgress();}));document.querySelectorAll('[data-table]').forEach(el=>el.addEventListener('input',()=>{const id=el.dataset.table;const v=Array.isArray(state.answers[id])?[...state.answers[id]]:Array(6).fill('');v[+el.dataset.cell]=el.value;state.answers[id]=v;persist();updateProgress();}));}
function navigate(delta){state.index+=delta;persist();renderExam();$('#question-title').focus();window.scrollTo({top:0,behavior:'smooth'});}
function tick(){if(state?.status!=='exam')return;const remaining=Math.max(0,state.started+DURATION-Date.now());const timer=$('#timer');if(timer){const sec=Math.ceil(remaining/1000);timer.textContent=`${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;timer.classList.toggle('urgent',remaining<5*60*1000);}if(remaining<=0)submit(true);}
async function submit(auto){if(state?.status!=='exam')return;if(!auto){const n=fields.filter(f=>!answered(f)).length;if(!await confirmAction('Hantar kertas jawapan?',n?`${n} ruang jawapan belum lengkap. Jawapan kosong mendapat 0 markah. Selepas dihantar, jawapan tidak boleh diubah.`:'Semua ruang sudah diisi. Selepas dihantar, jawapan tidak boleh diubah.','Hantar sekarang'))return;if(state.status!=='exam')return;}
 state.status='result';state.ended=Date.now();state.autoSubmitted=auto;state.confirmed=false;persist();$('#confirm').open&&$('#confirm').close();renderResults();window.scrollTo(0,0);}
function copyAnswer(f){const a=state.answers[f.id];if(f.type==='choice')return Number.isInteger(a)?f.options[a]:'Tidak dijawab';if(f.type==='table')return Array.isArray(a)?[a.slice(0,2),a.slice(2,4),a.slice(4,6)].map(r=>r.map(v=>v||'—').join(' | ')).join('\n'):'Tidak dijawab';return a||'Tidak dijawab';}
function renderResults(){const t=total(),p=t*2;$('#main').innerHTML=`<div class="eyebrow">SELESAI · ${esc(state.name||'PELAJAR SAINS')}</div><h1 style="font-size:38px">${state.confirmed?'Keputusan disahkan.':'Masa untuk semak & belajar.'}</h1><section class="score-hero"><div><div class="status">${state.confirmed?'MARKAH SELEPAS SEMAKAN IBU BAPA':'CADANGAN MARKAH · BELUM DISAHKAN'}</div><div class="score-number">${t}<small> / 50</small></div><span class="muted">${p}% · ${state.autoSubmitted?'Dihantar automatik apabila masa tamat':'Kertas telah dihantar'}</span></div><div class="grade" aria-label="Gred ${grade(p)}">${grade(p)}</div></section><div class="result-meta">${['A','B','C'].map((s,i)=>`<div class="card"><span class="muted">Bahagian ${s}</span><strong>${total(s)} / ${[10,8,32][i]}</strong><span class="muted">${s==='C'?(state.confirmed?'Disemak ibu bapa':'Cadangan kata kunci'):'Semakan automatik'}</span></div>`).join('')}</div><p class="grade-note">Gred latihan: A 80–100% · B 65–79% · C 50–64% · D 40–49% · E 0–39%. Ini skala latihan laman ini, bukan pengesahan gred atau tahap penguasaan rasmi sekolah.</p>${!state.confirmed?'<div class="notice"><strong>Semak Bahagian C sebelum sahkan gred.</strong> Sistem kata kunci boleh tersalah menilai ayat, penafian dan jawapan alternatif. Bandingkan setiap jawapan dengan skema. Buka mod ibu bapa untuk melaras markah.</div>':'<div class="notice">Markah bertulis telah disahkan melalui semakan ibu bapa pada peranti ini.</div>'}<div class="actions no-print"><button class="secondary" id="export">Muat turun keputusan</button><button class="secondary" id="print">Cetak / PDF</button><button id="parent">${state.parentMode?'Tutup mod ibu bapa':'Semak sebagai ibu bapa'}</button></div>${state.parentMode?'<div class="card review-mode no-print"><strong>Mod semakan ibu bapa</strong><p>Mod ini tiada kata laluan. Semak jawapan C satu demi satu dan pilih markah yang munasabah. Bukan sistem peperiksaan berpengawasan.</p><button id="confirm-grade">Sahkan semua markah & gred</button></div>':''}<h2 style="margin-top:32px">Jawapan & skema</h2>${QUESTIONS.map(q=>`<details class="card review" ${state.parentMode&&q.section==='C'?'open':''}><summary>Bahagian ${q.section} · ${esc(q.title)} <span class="score-tag">${q.fields.reduce((n,f)=>n+score(f),0)} / ${q.fields.reduce((n,f)=>n+f.max,0)}</span></summary><div class="review-body">${q.fields.map(f=>`<section class="review-field"><div class="field-label"><span>${esc(f.label)}</span><span class="score-tag">${score(f)} / ${f.max}</span></div><p class="muted">Jawapan kamu</p><div class="answer-copy">${esc(copyAnswer(f))}</div><p class="model"><strong>Skema:</strong> ${esc(f.model)}</p>${q.section==='C'?`<p class="muted" style="font-size:12px">${state.overrides?.[f.id]!==undefined?'Markah dilaras ibu bapa.':'Cadangan automatik; terima jawapan setara mengikut maksud sains.'}</p>${state.parentMode?`<label class="score-control">Markah ibu bapa<select data-score="${f.id}" aria-label="Markah ${f.id}">${Array.from({length:f.max+1},(_,i)=>`<option value="${i}" ${score(f)===i?'selected':''}>${i} / ${f.max}</option>`).join('')}</select></label>`:''}`:''}</section>`).join('')}</div></details>`).join('')}<div class="actions no-print"><button class="secondary" id="retry">Cuba sekali lagi</button></div><p class="privacy">Rekod percubaan ini disimpan pada pelayar ini sahaja. Muat turun keputusan untuk menyimpannya. Jawapan dan skema dimuatkan dalam pelayar untuk latihan kendiri.</p>`;
 $('#parent').onclick=()=>{state.parentMode=!state.parentMode;persist();renderResults();};$('#confirm-grade')?.addEventListener('click',async()=>{if(await confirmAction('Sahkan markah bertulis?','Sahkan bahawa setiap jawapan Bahagian C sudah dibandingkan dengan skema dan markah telah disemak.','Sahkan gred')){state.confirmed=true;state.parentMode=false;state.reviewedAt=Date.now();persist();renderResults();toast('Markah & gred disahkan.');}});
 document.querySelectorAll('[data-score]').forEach(el=>el.onchange=()=>{const open=[...document.querySelectorAll('details')].map(d=>d.open);const y=window.scrollY;state.overrides[el.dataset.score]=+el.value;state.confirmed=false;persist();renderResults();document.querySelectorAll('details').forEach((d,i)=>d.open=open[i]);window.scrollTo(0,y);});
 $('#print').onclick=()=>{const open=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true);window.print();document.querySelectorAll('details').forEach((d,i)=>d.open=open[i]);};$('#export').onclick=exportResults;$('#retry').onclick=async()=>{if(await confirmAction('Percubaan baharu?','Rekod pada peranti ini akan diganti. Muat turun keputusan dahulu jika perlu.','Mula semula')){const name=state.name;state=null;welcome();$('#student').value=name;}};}
function exportResults(){const data={exam:'UASA Sains Tahun 6 - Set latihan 01',name:state.name,started:new Date(state.started).toISOString(),submitted:new Date(state.ended).toISOString(),confirmed:state.confirmed,score:total(),maximum:50,percentage:total()*2,grade:grade(total()*2),gradeScale:'Latihan: A>=80 B>=65 C>=50 D>=40 E<40',answers:fields.map(f=>({section:f.section,question:f.id,answer:copyAnswer(f),model:f.model,score:score(f),maximum:f.max,marking:f.section==='C'?'Cadangan kata kunci / semakan ibu bapa':'Automatik'}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Keputusan_UASA_Sains_T6.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});welcome();
